CREATE MATERIALIZED VIEW gold.usage_charges_by_category_mv TO gold.usage_charges_by_category (`account_id` FixedString(64), `billing_month` Date, `category` String, `show_name` String, `metric` String, `quantity` Decimal(18, 6), `unit_price_usd` Decimal(18, 6), `charge_usd` Decimal(18, 6), `updated_at` DateTime64(3)) AS SELECT account_id, billing_month, category, show_name, 'stream_minutes' AS metric, CAST(countIf(is_active_final = 1) / 60., 'Decimal(18, 6)') AS quantity, CAST(0.0005 + ((cityHash64(show_name) % 16) * 0.0001), 'Decimal(18, 6)') AS unit_price_usd, CAST((countIf(is_active_final = 1) / 60.) * (0.0005 + ((cityHash64(show_name) % 16) * 0.0001)), 'Decimal(18, 6)') AS charge_usd, now64(3) AS updated_at FROM (SELECT user_id AS account_id, toStartOfMonth(minute_bucket) AS billing_month, finalizeAggregation(category) AS category, finalizeAggregation(show_name) AS show_name, finalizeAggregation(is_active) AS is_active_final FROM silver.session_minute_state) WHERE category != '' GROUP BY account_id, billing_month, category, show_name